/* Amora Life Path · PDF renderer (no reading texts here; they come from the server) */
(function(){
var FONTDATA={
"Playfair-BlackItalic":"",
"Playfair-Italic":"",
"EBGaramond":"",
"EBGaramond-Italic":"",
"EBGaramond-SemiBold":"",
"Jost":"",
};
function registerFonts(doc){
 for(var n in FONTDATA){
  doc.addFileToVFS(n+".ttf",FONTDATA[n]);
  doc.addFont(n+".ttf",n,"normal");
 }
}


/* ============================================================
   LIFE PATH · EN v1  (from Caminho de Vida v3)
   Life Path engine
   day, month and year reduced separately; masters 11/22/33 kept
   ============================================================ */

const MESTRES = new Set([11,22,33]);

function reduzir(n){
  while(n > 9 && !MESTRES.has(n)){
    n = String(n).split('').reduce((a,d)=>a + +d, 0);
  }
  return n;
}
const somaDigitos = n => String(n).split('').reduce((a,d)=>a + +d, 0);

function destino(d,m,y){
  const rd = reduzir(d), rm = reduzir(m), ry = reduzir(somaDigitos(y));
  return { dia:rd, mes:rm, ano:ry, num: reduzir(rd + rm + ry) };
}

/* English needs no reader-gender agreement: T only normalizes to string */
var RG = 'n';
function T(s){ return String(s); }

/* ============ ARCHETYPES ============ */
const ARQ = {
  1:'The Leader',            2:'The Diplomat',           3:'The Communicator',
  4:'The Builder',           5:'The Adventurer',         6:'The Nurturer',
  7:'The Seeker',            8:'The Powerhouse',         9:'The Sage',
  11:'The Inspired Healer',  22:'The Visionary Architect', 33:'The Master Teacher'
};
const arqNome  = n => ARQ[n];
const arqFrase = n => ARQ[n] + '’s Reading';

const EPITETO = {
  1:'The Pioneer',           2:'The Harmonizer',         3:'The Creative',
  4:'The Craftsperson',      5:'The Freedom Explorer',   6:'The Guardian',
  7:'The Inner Sage',        8:'The Influencer',         9:'The Humanitarian',
  11:'The Illuminator',      22:'The Master Builder',    33:'Universal Compassion'
};
const TEMA = {
  1:[21,9,9],   2:[8,17,20],  3:[22,11,19], 4:[9,17,10],  5:[22,15,7],
  6:[22,11,15], 7:[8,11,26],  8:[16,14,10], 9:[14,8,22],
  11:[12,8,26], 22:[11,14,17], 33:[19,11,13]
};

/* ============================================================
   TEXT BANKS
   ============================================================ */

let B = {}, DESAFIO = null;
/* ============================================================
   CHALLENGE NUMBERS
   Day, month and year reduced to one digit (no masters).
   1st = |day − month| · 2nd = |day − year| · main = |1st − 2nd| · last = |month − year|
   ============================================================ */

function reduz9(n){ while(n > 9) n = String(n).split('').reduce((a,d)=>a + +d, 0); return n; }

function desafios(d, m, y){
  const rd = reduz9(d), rm = reduz9(m), ry = reduz9(y);
  const d1 = Math.abs(rd - rm), d2 = Math.abs(rd - ry);
  return { d1, d2, principal: Math.abs(d1 - d2), ultimo: Math.abs(rm - ry) };
}

const PW=210, PH=297, ML=38, MR=22, MT=30, MB=26;
const CW = PW-ML-MR;              /* 150 */
const RAIL = 22;                  /* left rail */

/* solar palette — cream, honey, amber, ember */
const C = {
  areia:[255,249,239], areia2:[255,238,212], creme:[255,252,246],
  tinta:[58,29,10],    grafite:[96,62,36],   fraco:[168,132,100],
  ouro:[184,82,12],    ouroClaro:[255,170,40],
  terra:[214,88,10],   terraPale:[255,208,156],
  linha:[242,214,176], coral:[217,69,46]
};

const F = { disp:'Playfair-BlackItalic', dest:'Playfair-Italic',
            body:'EBGaramond', it:'EBGaramond-Italic',
            sb:'EBGaramond-SemiBold', util:'Jost' };

let doc, y, page, nomeCliente, numDestino;

const mm = pt => pt*0.352778;
const ehMestre = n => MESTRES.has(+n);

/* ============ AURAS ============
   radial gradients drawn on canvas and embedded as transparent PNGs,
   generated once and reused on every page. */
const AURA_STOPS = {
  sol:    [[0,'rgba(255,255,255,1)'],[.10,'rgba(255,251,214,1)'],[.26,'rgba(255,243,107,1)'],[.40,'rgba(255,210,58,1)'],
           [.54,'rgba(255,176,32,1)'],[.66,'rgba(255,142,31,1)'],[.74,'rgba(255,142,31,.45)'],[.82,'rgba(255,142,31,0)'],[1,'rgba(255,142,31,0)']],
  mestre: [[0,'rgba(255,255,255,1)'],[.10,'rgba(255,241,222,1)'],[.28,'rgba(255,201,138,1)'],[.44,'rgba(255,154,92,1)'],
           [.58,'rgba(242,96,58,1)'],[.68,'rgba(217,69,46,1)'],[.76,'rgba(217,69,46,.4)'],[.84,'rgba(217,69,46,0)'],[1,'rgba(217,69,46,0)']],
  halo:   [[0,'rgba(255,250,215,.95)'],[.22,'rgba(255,232,110,.8)'],[.45,'rgba(255,190,60,.5)'],[.70,'rgba(255,150,40,.18)'],[1,'rgba(255,140,30,0)']],
  haloM:  [[0,'rgba(255,240,225,.95)'],[.22,'rgba(255,200,150,.8)'],[.45,'rgba(250,140,90,.5)'],[.70,'rgba(225,80,50,.18)'],[1,'rgba(217,69,46,0)']]
};
const _aura = {};
function auraURL(tipo){
  if(_aura[tipo]) return _aura[tipo];
  const s = 512, cv = document.createElement('canvas'); cv.width = cv.height = s;
  const g = cv.getContext('2d'), gr = g.createRadialGradient(s/2,s/2,0,s/2,s/2,s/2);
  AURA_STOPS[tipo].forEach(([o,c])=>gr.addColorStop(o,c));
  g.fillStyle = gr; g.fillRect(0,0,s,s);
  return (_aura[tipo] = cv.toDataURL('image/png'));
}
function opac(o){ doc.setGState(new doc.GState({opacity:o})); }
/* aura centered at (cx,cy); w×h is the gradient box (elliptical if w≠h) */
function aura(tipo,cx,cy,w,h,o){
  h = h || w;
  if(o!==undefined && o<1) opac(o);
  doc.addImage(auraURL(tipo),'PNG',cx-w/2,cy-h/2,w,h,'aura_'+tipo,'FAST');
  if(o!==undefined && o<1) opac(1);
}
const tipoSol  = n => ehMestre(n) ? 'mestre' : 'sol';
const tipoHalo = n => ehMestre(n) ? 'haloM'  : 'halo';

/* --- page: cream background + soft auras alternating sides --- */
function newPage(bg, semAura){
  if(page>0) doc.addPage();
  page++;
  const c = bg || C.areia;
  doc.setFillColor(c[0],c[1],c[2]);
  doc.rect(0,0,PW,PH,'F');
  if(!semAura){
    const h = tipoHalo(numDestino);
    if(page%2){ aura(h, PW-6, 4, 150, 150, .55); aura(h, -6, PH-10, 110, 110, .28); }
    else      { aura(h, 8, 10, 130, 130, .42);   aura(h, PW+4, PH-30, 140, 140, .32); }
  }
  y = MT;
}
const room = h => y+h <= PH-MB;
function need(h,bg){ if(!room(h)) newPage(bg); }

function setStyle(s){
  switch(s){
    case 'sb':   doc.setFont(F.sb,'normal');   doc.setTextColor(...C.ouro);   break;
    case 'it':   doc.setFont(F.it,'normal');   doc.setTextColor(...C.grafite);break;
    case 'soft': doc.setFont(F.body,'normal'); doc.setTextColor(...C.grafite);break;
    default:     doc.setFont(F.body,'normal'); doc.setTextColor(...C.tinta);
  }
}

function drawRich(runs, opt){
  opt = opt || {};
  const size = opt.size||12.6, lh = mm(size)*(opt.lh||1.68);
  const x0 = opt.x!==undefined?opt.x:ML, w = opt.w||CW;
  doc.setFontSize(size);
  const words=[];
  runs.forEach(r=>{
    const st = r.s||'body';
    String(r.t).split(/(\s+)/).forEach(tk=>{ if(tk!=='') words.push({t:tk,s:st}); });
  });
  let line=[], lw=0;
  const flush=()=>{
    if(!line.length) return;
    need(lh, opt.bg);
    let x = x0;
    if(opt.align==='center'){
      let tw=0; line.forEach(t=>{setStyle(t.s);doc.setFontSize(size);tw+=doc.getTextWidth(t.t)});
      x = x0 + (w-tw)/2;
    }
    line.forEach(t=>{ setStyle(t.s); doc.setFontSize(size); doc.text(t.t,x,y); x+=doc.getTextWidth(t.t); });
    y += lh; line=[]; lw=0;
  };
  words.forEach(tk=>{
    setStyle(tk.s); doc.setFontSize(size);
    const tw = doc.getTextWidth(tk.t);
    if(/^\s+$/.test(tk.t)){ if(line.length){ line.push(tk); lw+=tw; } return; }
    if(lw+tw>w && line.length){
      while(line.length && /^\s+$/.test(line[line.length-1].t)) line.pop();
      flush();
    }
    line.push(tk); lw+=tw;
  });
  flush();
  y += opt.after!==undefined ? opt.after : mm(size)*0.78;
}
const para = (txt,opt)=>drawRich([{t:T(txt)}], opt);

/* --- Playfair Black Italic title with the last word in ember --- */
function linhaAcento(l, x, yy, cor, acento, soUltima){
  let i = l.lastIndexOf(' ');
  if(!soUltima && i>0 && l.length-i-1<=2){ const j=l.lastIndexOf(' ',i-1); if(j>=0) i=j; }  /* keep short last words together */
  if(i<0){ doc.setTextColor(...acento); doc.text(l,x,yy); return; }
  const a = l.slice(0,i+1), b = l.slice(i+1);
  doc.setTextColor(...cor);    doc.text(a,x,yy);
  doc.setTextColor(...acento); doc.text(b,x+doc.getTextWidth(a),yy);
}
function tituloCentro(txt, yy, size, cor, acento, soUltima){
  doc.setFont(F.disp,'normal'); doc.setFontSize(size);
  const tw = doc.getTextWidth(txt);
  linhaAcento(txt,(PW-tw)/2,yy,cor||C.tinta,acento||C.terra,soUltima);
}

/* --- kicker on the left rail --- */
function kicker(txt,bg){
  need(10,bg);
  doc.setFont(F.util,'normal'); doc.setFontSize(7.6); doc.setTextColor(...C.ouro);
  doc.setCharSpace(0.85); doc.text(String(txt).toUpperCase(),ML,y); doc.setCharSpace(0);
  doc.setDrawColor(...C.ouroClaro); doc.setLineWidth(0.5);
  doc.line(RAIL,y-1.1,ML-5,y-1.1);
  aura('sol', RAIL, y-1.1, 4.6, 4.6);
  y += 7.2;
}

function h1(txt,bg){
  const size=28, lh=mm(size)*1.1;
  doc.setFont(F.disp,'normal'); doc.setFontSize(size);
  const lines = doc.splitTextToSize(txt,CW);
  need(lh*lines.length+9,bg);
  y += mm(size)*0.80;
  lines.forEach((l,i)=>{
    if(i===lines.length-1) linhaAcento(l,ML,y,C.tinta,C.terra);
    else { doc.setTextColor(...C.tinta); doc.text(l,ML,y); }
    y+=lh;
  });
  y += 5.4;
}

function h2(txt,bg){
  need(15,bg); y += 5.2;
  doc.setFont(F.disp,'normal'); doc.setFontSize(14); doc.setTextColor(...C.terra);
  doc.text(T(txt),ML,y);
  y += 7.8;
}

function lead(txt,bg){
  const size=14, lh=mm(size)*1.5;
  doc.setFont(F.dest,'normal'); doc.setFontSize(size); doc.setTextColor(...C.grafite);
  const lines = doc.splitTextToSize(T(txt),CW);
  need(lh*lines.length+7,bg);
  lines.forEach(l=>{ doc.text(l,ML,y); y+=lh; });
  y += 6.4;
}

/* --- labeled box: peach card with a small sun on the label --- */
function caixa(rotulo,txt,bg){
  const size=11.6, lh=mm(size)*1.58, pad=7, w=CW-pad*2;
  doc.setFont(F.body,'normal'); doc.setFontSize(size);
  const lines = doc.splitTextToSize(T(txt),w);
  const alt = lh*lines.length + pad*2 + 6;
  need(alt+4,bg);
  const top = y-2;
  doc.setFillColor(...C.areia2);
  doc.roundedRect(ML,top,CW,alt,3.2,3.2,'F');
  let yy = top+pad+1;
  aura('sol', ML+pad+1.8, yy-1.2, 6.2, 6.2);
  doc.setFont(F.util,'normal'); doc.setFontSize(7.2); doc.setTextColor(...C.ouro);
  doc.setCharSpace(0.8); doc.text(String(rotulo).toUpperCase(),ML+pad+5.6,yy); doc.setCharSpace(0);
  yy += 6;
  doc.setFont(F.body,'normal'); doc.setFontSize(size); doc.setTextColor(...C.tinta);
  lines.forEach(l=>{ doc.text(l,ML+pad,yy); yy+=lh; });
  y = top+alt+7;
}

/* --- affirmation: centered, over a halo, between two rules --- */
function afirmacao(txt,rotulo,bg){
  const size=15, lh=mm(size)*1.45;
  doc.setFont(F.dest,'normal'); doc.setFontSize(size);
  const lines = doc.splitTextToSize('“'+T(txt)+'”',CW-24);
  const alt = lh*lines.length + 20;
  need(alt+6,bg);
  y += 6;
  aura(tipoHalo(numDestino), PW/2+(ML-MR)/2, y+alt/2-4, CW*0.95, alt*1.9, .55);
  doc.setDrawColor(...C.terraPale); doc.setLineWidth(0.5);
  doc.line(ML+30,y,PW-MR-30,y);
  y += mm(size)*0.95;
  doc.setFont(F.dest,'normal'); doc.setFontSize(size); doc.setTextColor(...C.terra);
  lines.forEach(l=>{
    const tw = doc.getTextWidth(l);
    doc.text(l, ML+(CW-tw)/2, y); y += lh;
  });
  y += 2.5;
  doc.setDrawColor(...C.terraPale);
  doc.line(ML+30,y,PW-MR-30,y);
  y += 5.4;
  doc.setFont(F.util,'normal'); doc.setFontSize(7); doc.setTextColor(...C.ouro);
  doc.setCharSpace(0.9);
  const t2 = String(rotulo).toUpperCase();
  doc.text(t2, ML+(CW-doc.getTextWidth(t2)-0.9*(t2.length-1))/2, y);
  doc.setCharSpace(0);
  y += 9;
}

/* --- 2×3 grid of gifts --- */
function grade(itens,bg){
  const gap=8, cw=(CW-gap)/2, size=10.4, lh=mm(size)*1.5;
  for(let i=0;i<itens.length;i+=2){
    const par = itens.slice(i,i+2);
    doc.setFont(F.body,'normal'); doc.setFontSize(size);
    let alt = 0;
    const blocos = par.map(it=>{
      const ls = doc.splitTextToSize(T(it.d),cw-2);
      alt = Math.max(alt, lh*ls.length);
      return ls;
    });
    const total = alt + 12;
    need(total+3,bg);
    const top = y;
    par.forEach((it,k)=>{
      const x = ML + k*(cw+gap);
      doc.setDrawColor(...C.ouroClaro); doc.setLineWidth(0.45);
      doc.line(x+3,top-2,x+cw,top-2);
      aura('sol', x+1, top-2, 3.6, 3.6);
      doc.setFont(F.util,'normal'); doc.setFontSize(7.4); doc.setTextColor(...C.ouro);
      doc.setCharSpace(0.75); doc.text(T(it.t).toUpperCase(),x,top+3.4); doc.setCharSpace(0);
      doc.setFont(F.body,'normal'); doc.setFontSize(size); doc.setTextColor(...C.tinta);
      let yy = top+9.4;
      blocos[k].forEach(l=>{ doc.text(l,x,yy); yy+=lh; });
    });
    y = top + total + 4;
  }
  y += 3;
}

/* --- optical centering: getTextWidth ignores charSpace, so add it by hand --- */
function centrado(txt,yy,cs){
  const t = String(txt);
  const extra = cs ? cs*Math.max(0,t.length-1) : 0;
  const tw = doc.getTextWidth(t) + extra;
  doc.text(t,(PW-tw)/2,yy);
  return tw;
}

/* --- solar seal: aura orb with the numeral in its white center --- */
function selo(cx,cy,r,txt,opt){
  opt = opt || {};
  const n = String(txt), M = ehMestre(txt);
  if(r>=10) aura(M?'haloM':'halo', cx, cy, r*3.4, r*3.4, .6);
  aura(M?'mestre':'sol', cx, cy, r*2/0.82, r*2/0.82);
  if(r>=10){
    doc.setLineDashPattern([0.7,1.4],0);
    doc.setDrawColor(...C.ouro); doc.setLineWidth(0.25); opac(.45);
    doc.circle(cx,cy,r*0.64,'S');
    opac(1); doc.setLineDashPattern([],0);
  }
  doc.setFont(F.disp,'normal');
  const fs = r*(n.length>1?1.35:1.75);
  doc.setFontSize(fs); doc.setTextColor(...(opt.cor||C.tinta));
  const tw = doc.getTextWidth(n);
  doc.text(n, cx-tw/2, cy + mm(fs)*0.34);
}

/* --- cover --- */
function capa(num,nome,dataLabel){
  newPage(C.areia, true);
  aura(tipoHalo(num), 18, 30, 170, 170, .5);
  aura(tipoHalo(num), PW-10, PH-24, 190, 190, .55);

  doc.setDrawColor(...C.ouroClaro); doc.setLineWidth(0.5);
  doc.roundedRect(13,13,PW-26,PH-26,4,4,'S');
  doc.setDrawColor(...C.terraPale); doc.setLineWidth(0.25);
  doc.roundedRect(15.6,15.6,PW-31.2,PH-31.2,3,3,'S');

  doc.setFont(F.util,'normal'); doc.setFontSize(7.6); doc.setTextColor(...C.ouro);
  doc.setCharSpace(1.5);
  centrado('PERSONAL NUMEROLOGY READING',34,1.5);
  doc.setCharSpace(0);

  selo(PW/2, 90, 33, num);

  tituloCentro('Life Path Number '+num,152,31,null,null,true);

  doc.setFont(F.dest,'normal'); doc.setFontSize(17); doc.setTextColor(...C.terra);
  centrado(arqFrase(num),164);

  doc.setFont(F.util,'normal'); doc.setFontSize(7.4); doc.setTextColor(...C.ouro);
  doc.setCharSpace(1.1);
  centrado(EPITETO[num].toUpperCase(),173,1.1);
  doc.setCharSpace(0);

  doc.setDrawColor(...C.ouroClaro); doc.setLineWidth(0.5);
  doc.line(PW/2-16,179,PW/2+16,179);
  aura('sol', PW/2, 179, 4.2, 4.2);

  doc.setFont(F.body,'normal'); doc.setFontSize(12.4); doc.setTextColor(...C.grafite);
  const linhas = doc.splitTextToSize(
    T('This reading was prepared for you, so that you can recognize the strength you carry and understand the depth of the path your numbers reveal.'), 116);
  let yy = 193;
  linhas.forEach(l=>{ centrado(l,yy); yy+=7.2; });

  if(nome){
    doc.setFont(F.disp,'normal'); doc.setFontSize(24); doc.setTextColor(...C.tinta);
    centrado(nome,240);
  }
  if(dataLabel){
    doc.setFont(F.util,'normal'); doc.setFontSize(8.4); doc.setTextColor(...C.ouro);
    doc.setCharSpace(0.9);
    centrado(dataLabel,249,0.9);
    doc.setCharSpace(0);
  }

  doc.setFont(F.util,'normal'); doc.setFontSize(7); doc.setTextColor(...C.ouro);
  doc.setCharSpace(1.4);
  centrado('NUMEROLOGY · SELF-KNOWLEDGE · LIFE PATH',PH-26,1.4);
  doc.setCharSpace(0);
}

/* --- chapter opener: solar orb with the numeral, above the title --- */
const ROM = ['','I','II','III','IV','V','VI','VII','VIII'];
function capitulo(n,titulo){
  newPage();
  selo(ML+13, MT+16, 15, n, {cor:C.tinta});
  doc.setFont(F.util,'normal'); doc.setFontSize(7.6); doc.setTextColor(...C.ouro);
  doc.setCharSpace(1.2); doc.text('CHAPTER '+ROM[n],ML,MT+44); doc.setCharSpace(0);
  doc.setDrawColor(...C.ouroClaro); doc.setLineWidth(0.5);
  doc.line(RAIL,MT+42.9,ML-5,MT+42.9);
  aura('sol', RAIL, MT+42.9, 4.6, 4.6);
  y = MT + 48;
  h1(titulo);
}

/* --- footer --- */
function rodapes(semUltima){
  const n = doc.getNumberOfPages() - (semUltima?1:0);
  for(let i=2;i<=n;i++){
    doc.setPage(i);
    doc.setDrawColor(...C.linha); doc.setLineWidth(0.3);
    doc.line(ML,PH-18,PW-MR,PH-18);
    doc.setFont(F.util,'normal'); doc.setFontSize(7.2); doc.setTextColor(...C.fraco);
    doc.setCharSpace(0.6);
    doc.text((nomeCliente||'').toUpperCase(),ML,PH-13.4);
    doc.setCharSpace(0);
    doc.text(String(i-1),PW-MR,PH-13.4,{align:'right'});
    selo(RAIL+2, PH-15.6, 5.4, numDestino, {cor:C.tinta});
  }
}

/* ============================================================
   ASSEMBLY
   ============================================================ */
const MESES = ['January','February','March','April','May','June','July','August',
  'September','October','November','December'];

function build(c){
  RG = c.rg;
  nomeCliente = c.name || 'Your reading';
  const dst = destino(c.d,c.m,c.y);
  const n = dst.num;
  numDestino = n;

  const b = B[n];
  doc = new jspdf.jsPDF({unit:'mm',format:'a4'});
  registerFonts(doc);
  page = 0;

  const dataLabel = MESES[c.m-1].toUpperCase()+' '+c.d+', '+c.y;
  capa(n, c.name, dataLabel);

  if(!b){
    newPage();
    kicker('in progress');
    h1('Life Path '+n);
    para('The text bank for Life Path Number '+n+' has not been written yet. This PDF is only the cover, for layout checking.');
    rodapes();
    return doc;
  }

  newPage();
  kicker('Where it all begins');
  h1('A message for you');
  lead(b.abertura.lead);
  b.abertura.p.forEach(p=>para(p));
  caixa('What the '+n+' carries', b.abertura.caixa);
  b.abertura.p2.forEach(p=>para(p));

  capitulo(1,'Who you are');
  lead(b.quem.lead);
  b.quem.p.forEach(p=>para(p));
  h2('Your natural gifts');
  if(b.donsIntro) para(b.donsIntro);
  grade(b.dons);
  h2('Your deepest essence');
  b.essencia.p.forEach(p=>para(p));
  afirmacao(b.essencia.af,'Affirmation of the '+n);

  capitulo(2,'Your life mission');
  lead(b.missao.lead);
  para(b.missao.intro);
  b.missao.mov.forEach((mv,i)=>{
    h2(mv.t);
    mv.p.forEach(p=>para(p));
    if(i===0) caixa('A reflection for you', b.missao.reflexao);
  });
  if(b.missao.decisao) caixa('The decision that keeps returning', b.missao.decisao);
  h2('What your mission is NOT');
  b.missao.nao.forEach(p=>para(p));

  capitulo(3,'Your shadows');
  lead(b.sombras.lead);
  b.sombras.s.forEach((sb,i)=>{
    h2(sb.t);
    sb.p.forEach(p=>para(p));
    if(i===1) caixa('Warning sign', b.sombras.alerta);
    if(i===2) caixa('To reflect on', b.sombras.refletir);
  });
  afirmacao(b.sombras.af,'Affirmation of integration');

  capitulo(4,'Love and relationships');
  lead(b.amor.lead);
  h2('What you need in a relationship');
  b.amor.precisa.forEach(p=>para(p));
  h2('The relationship pattern of the '+n);
  b.amor.padrao.forEach(p=>para(p));
  h2('Compatibility and resonance');
  b.amor.compat.forEach(p=>para(p));
  afirmacao(b.amor.af,'Affirmation for love');

  capitulo(5,'Career and purpose');
  lead(b.carreira.lead);
  h2('Where you flourish');
  b.carreira.floresce.forEach(p=>para(p));
  caixa('Where the '+n+' flourishes', b.carreira.areas);
  h2('Where you struggle');
  b.carreira.sofre.forEach(p=>para(p));
  h2('Your relationship with recognition');
  b.carreira.reconhecimento.forEach(p=>para(p));
  afirmacao(b.carreira.af,'Affirmation for work');

  capitulo(6,'Health and wellbeing');
  lead(b.saude.lead);
  h2('Your physical patterns');
  b.saude.fisico.forEach(p=>para(p));
  caixa('What your body needs', b.saude.corpo);
  h2('Your emotional health');
  b.saude.emocional.forEach(p=>para(p));

  capitulo(7,'Spirituality and growth');
  lead(b.espirito.lead);
  h2('The sacred for the '+n);
  b.espirito.sagrado.forEach(p=>para(p));
  h2('Your deepest lesson');
  b.espirito.licao.forEach(p=>para(p));
  h2('Practices that nourish the '+n);
  b.espirito.praticas.forEach(p=>para(p));
  afirmacao(b.espirito.af,'Spiritual affirmation');

  const dz = desafios(c.d,c.m,c.y);
  const POS = ['d1','d2','principal','ultimo'];
  capitulo(8,'Your Challenge Numbers');
  lead(DESAFIO.lead);
  DESAFIO.intro.forEach(p=>para(p));
  grade(POS.map(k=>({t:DESAFIO.posicoes[k].t+' · '+dz[k], d:DESAFIO.n[dz[k]].nome+', '+DESAFIO.posicoes[k].quando+'.'})));
  const vistos = new Set();
  POS.forEach(k=>{
    const v = dz[k], ps = DESAFIO.posicoes[k];
    h2(ps.t+' · number '+v);
    para(ps.txt);
    if(vistos.has(v)) para(DESAFIO.repetido);
    else { DESAFIO.n[v].p.forEach(p=>para(p)); vistos.add(v); }
    if(k==='principal') caixa('Your main challenge', DESAFIO.n[v].nome+'. It is the lesson that runs through your whole life and that, met with patience, becomes one of your greatest strengths.');
  });
  afirmacao(DESAFIO.af,'Affirmation of the challenges');

  newPage();
  selo(PW/2, MT+16, 14, n);
  y = MT + 46;
  tituloCentro('A last word for you',y,24);
  y += 16;
  b.fecho.p.forEach(p=>drawRich([{t:T(p)}],{align:'center',size:12.8,after:5.4}));

  newPage(C.areia, true);
  aura(tipoHalo(n), PW/2, 136, 230, 230, .75);
  aura(tipoSol(n),  PW/2, 136, 192, 192, .9);
  doc.setDrawColor(...C.ouroClaro); doc.setLineWidth(0.5);
  doc.roundedRect(15,15,PW-30,PH-30,4,4,'S');
  doc.setFont(F.dest,'normal'); doc.setFontSize(17); doc.setTextColor(...C.tinta);
  const lc = doc.splitTextToSize('“'+T(b.fecho.citacao)+'”', 112);
  let yy = 136 - (lc.length-1)*10.2/2 + 4;
  lc.forEach(l=>{ centrado(l,yy); yy+=10.2; });
  doc.setFont(F.util,'normal'); doc.setFontSize(7); doc.setTextColor(...C.ouro);
  doc.setCharSpace(1.3);
  centrado('NUMEROLOGY READING · LIFE PATH NUMBER '+n,PH-34,1.3);
  doc.setCharSpace(0);

  rodapes(true);   /* the quote page stays clean */
  return doc;
}

function filename(c){
  const p = v => String(v).padStart(2,'0');
  const base = (c.name||'reading').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^A-Za-z0-9]+/g,'_').replace(/^_+|_+$/g,'');
  return 'Life_Path_'+(base||'reading')+'_'+c.y+p(c.m)+p(c.d)+'.pdf';
}


window.LPR = {
  build: function(n){
    B = {}; B[n.n] = n.b; DESAFIO = n.des;
    return build({ name: n.name, d: n.d, m: n.m, y: n.y, rg: 'n', prod: 'lifepath' });
  }
};
})();
